<script src="../../script.js"></script>
<script>
const form = document.getElementById("interestForm");
const statusBox = document.getElementById("interestStatus");
const submit = document.getElementById("interestSubmit");
form.addEventListener("submit", async event => {
  event.preventDefault();
  statusBox.className = "form-status";
  statusBox.textContent = "Sending...";
  submit.disabled = true;
  try {
    const response = await fetch(form.action, { method: "POST", body: new FormData(form), headers: { "Accept": "application/json" } });
    const result = await response.json();
    if (result.type === "success") {
      form.hidden = true;
      document.getElementById("interestSent").hidden = false;
    } else {
      statusBox.className = "form-status error";
      statusBox.textContent = result.message || "Registration failed. Please try again.";
    }
  } catch (_err) {
    statusBox.className = "form-status error";
    statusBox.textContent = "Registration failed. Please try again.";
  } finally {
    submit.disabled = false;
  }
});
</script>
